CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY, c1 ANY) STRICT;
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER, c1 TEXT UNIQUE, c2 REAL UNIQUE, c3 BLOB, ref INTEGER REFERENCES t0(id));
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', -2, 3), instr('theta', '-7'), replace('theta', 'e', ''), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '%é%', 'theta' GLOB 'a*', char(66, 970), 'theta' || '-7', 'theta' < '-7', 'theta' = '-7' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 3, 1), instr('-7', 'alpha'), replace('-7', 'é', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '%a_', '-7' GLOB '*[a-m]*', char(84, 784), '-7' || 'alpha', '-7' < 'alpha', '-7' = 'alpha' COLLATE NOCASE;
SELECT length('omicron'), upper('omicron'), lower('omicron'), substr('omicron', 1, 0), instr('omicron', '-7'), replace('omicron', 'e', ''), trim('omicron'), ltrim('omicron', 'ab'), hex('omicron'), quote('omicron'), unicode('omicron'), 'omicron' LIKE 'A%', 'omicron' GLOB '*', char(87, 388), 'omicron' || '-7', 'omicron' < '-7', 'omicron' = '-7' COLLATE NOCASE;
SELECT length('omicron'), upper('omicron'), lower('omicron'), substr('omicron', 3, 4), instr('omicron', 'omicron'), replace('omicron', 'a', 'XY'), trim('omicron'), ltrim('omicron', 'ab'), hex('omicron'), quote('omicron'), unicode('omicron'), 'omicron' LIKE '%', 'omicron' GLOB '?', char(68, 481), 'omicron' || 'omicron', 'omicron' < 'omicron', 'omicron' = 'omicron' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', 3, 5), instr(' pad ', 'chi'), replace(' pad ', '', '_'), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '%a_', ' pad ' GLOB 'a*', char(86, 992), ' pad ' || 'chi', ' pad ' < 'chi', ' pad ' = 'chi' COLLATE NOCASE;
UPDATE t1 SET c0 = nullif(c2 BETWEEN 3 AND NULL, coalesce(ref, -4)) WHERE NULL IN ((c1 IS NOT c3), NULL, 'phi');
DELETE FROM t1 WHERE id % 2 = 0;
SELECT * FROM t1 ORDER BY id, c0 DESC, c1, c2, c3 DESC, ref;
SELECT a.id, b.id, a.c0, b.c2 FROM t1 a LEFT OUTER JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 46;
SELECT count(*) FROM t1 a JOIN t1 b USING(id) WHERE a.typeof(c2) IN (c2 IS NULL, '日本', 'über');
